func astNode(v any) *Node { n, _ := v.(*Node); return n }
func astIsNil(v any) bool { n, ok := v.(*Node); return v == nil || ok && n == nil }

// astKid returns the value of element i of a tuple node's children (nil if there is none).
func astKid(kids []*Node, i int) any {
	if i < len(kids) {
		return UnboxNode(kids[i])
	}
	return nil
}

// The value of a rule, and a list element, holds an int, string or bool in a box.
func astInt(v any) int       { i, _ := UnboxValue(v).(int); return i }
func astString(v any) string { s, _ := UnboxValue(v).(string); return s }
func astBool(v any) bool     { x, _ := UnboxValue(v).(bool); return x }
func astPtrInt(v any) *int {
	if i, ok := UnboxValue(v).(int); ok {
		return &i
	}
	return nil
}
func astPtrString(v any) *string {
	if s, ok := UnboxValue(v).(string); ok {
		return &s
	}
	return nil
}
func astPtrBool(v any) *bool {
	if x, ok := UnboxValue(v).(bool); ok {
		return &x
	}
	return nil
}

// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free      []T
	next      int
	bootstrap uint8
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew allocates the first three values independently so a later
// published value cannot retain discarded early siblings through a chunk.
// Later values use the original 8-to-256 chunk growth.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		if s.bootstrap < 3 {
			s.bootstrap++
			return new(T)
		}
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice allocates the first nonempty small list independently to keep
// its backing values separate from later published lists of the same type.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		if s.bootstrap == 0 {
			s.bootstrap = 1
			return make([]T, n)
		}
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

// tinit sets up the typed rules (called at the end of init, after the rule tables).
func tinit() {
	tnamedPub := func(a any, x TVal) any {
		s, _ := a.(*tslabs)
		if s == nil {
			s = &tslabs{}
		}
		switch x.TName() {
		case "Attribute":
			return tv26(s, x)
		case "Bool":
			return tv44(s, x)
		case "Bottom":
			return tv46(s, x)
		case "Float":
			return tv54(s, x)
		case "Ident":
			return tv0(s, x)
		case "Int":
			return tv48(s, x)
		case "Null":
			return tv45(s, x)
		}
		return nil
	}
	for i, name := range []string{"Attribute", "Bool", "Bottom", "Float", "Ident", "Int", "Null"} {
		tnt[i+1] = TRegisterNodeType(name, tnamedPub)
	}
	trules[8].Nt = tnt[5]
	trules[42].Nt = tnt[5]
	trules[43].Nt = tnt[5]
	trules[44].Nt = tnt[5]
	trules[55].Nt = tnt[5]
	trules[66].Nt = tnt[5]
	trules[67].Nt = tnt[5]
	trules[68].Nt = tnt[5]
	trules[69].Nt = tnt[5]
	trules[70].Nt = tnt[5]
	trules[73].Nt = tnt[5]
	trules[74].Nt = tnt[5]
	trules[77].Nt = tnt[5]
	trules[102].Nt = tnt[5]
	trules[118].Nt = tnt[5]
	trules[121].Nt = tnt[1]
	trules[122].Nt = tnt[1]
	trules[139].Nt = tnt[5]
	trules[141].Nt = tnt[5]
	trules[142].Nt = tnt[2]
	trules[143].Nt = tnt[7]
	trules[144].Nt = tnt[3]
	trules[148].Nt = tnt[6]
	trules[154].Nt = tnt[4]
	trules[155].Nt = tnt[6]
}

// tmk_Alias makes a Alias in an action (newStruct in the typed runtime).
func tmk_Alias(c *TActCtx, final bool, f0 any, f1 any) any {
	c.P.StepWork()
	a := c.P.Ext.(*tslabs)
	v := astNew(&a.tAlias)
	c.P.StepWork()
	v.Ident = tv0(a, f0)
	c.P.StepWork()
	v.Expr = TAs[Expr](TPubIn(a, f1))
	if final {
		v.Span = Span{c.Start, c.End}
		return v
	}
	first, start, end := true, 0, 0
	c.P.StepWork()
	FieldSpanOf(f0, &first, &start, &end)
	c.P.StepWork()
	FieldSpanOf(f1, &first, &start, &end)
	return c.Made(v, first, start, end)
}

