func tv131(a *tslabs, v any) *TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]] {
	a.stepWork()
	switch x := v.(type) {
	case *TSeq:
		if x.Typ == TypeTupleValue || x.Typ == TypeListValue {
			return nil
		}
		out := &TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]{Span: x.Span}
		out.Value = tl8(a, x)
		return out
	case *TError:
		return nil
	case TVal:
		if x.TStruct() {
			return nil
		}
		s, e := x.TSpan()
		text, _ := x.TText()
		_ = text
		out := &TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]{Span: Span{s, e}}
		out.Value = tl8(a, text)
		return out
	}
	return nil
}

func tv132(a *tslabs, v any) *TNode[Tuple3[*TNode[string], *TNode[string], *TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]]] {
	a.stepWork()
	switch x := v.(type) {
	case *TSeq:
		if x.Typ == TypeTupleValue || x.Typ == TypeListValue {
			return nil
		}
		out := &TNode[Tuple3[*TNode[string], *TNode[string], *TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]]]{Span: x.Span}
		out.Value = tv133(a, x)
		return out
	case *TError:
		return nil
	case TVal:
		if x.TStruct() {
			return nil
		}
		s, e := x.TSpan()
		text, _ := x.TText()
		_ = text
		out := &TNode[Tuple3[*TNode[string], *TNode[string], *TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]]]{Span: Span{s, e}}
		out.Value = tv133(a, text)
		return out
	}
	return nil
}

func tv133(a *tslabs, v any) Tuple3[*TNode[string], *TNode[string], *TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]] {
	a.stepWork()
	var out Tuple3[*TNode[string], *TNode[string], *TNode[[]*TNode[Tuple2[*TNode[string], *TNode[string]]]]]
	x, _ := v.(*TSeq)
	if x == nil {
		return out
	}
	out.E0 = TPubMatch(TKid(x.Kids, 0))
	out.E1 = TPubMatch(TKid(x.Kids, 1))
	out.E2 = tv131(a, TKid(x.Kids, 2))
	return out
}

func tl5(a *tslabs, v any) []*TNode[string] {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*TSeq)
	if n == nil {
		return []*TNode[string]{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl5Chunk, len(n.Kids))
	for i, c := range n.Kids {
		a.stepWork()
		out[i] = TPubMatch(c)
	}
	return out
}

func tl6(a *tslabs, v any) []any {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*TSeq)
	if n == nil {
		return []any{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl6Chunk, len(n.Kids))
	for i, c := range n.Kids {
		a.stepWork()
		out[i] = TPubIn(a, c)
	}
	return out
}

